const BLIND_SCHEMA = {
  type: 'object',
  properties: {
    answers: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          idx: { type: 'integer' },
          answer_index: { type: 'integer', description: '你判定的正解選項(0-based)' },
          single_answer: { type: 'boolean', description: '是否恰好只有一個明確正解(無歧義、無多重正確、無「以上皆是」式模糊)' },
        },
        required: ['idx', 'answer_index', 'single_answer'],
      },
    },
  },
  required: ['answers'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    judgments: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          idx: { type: 'integer' },
          belongs: { type: 'boolean', description: '題目是否屬於本課考點範疇(非跨課、非超綱)' },
          match: { type: 'boolean', description: '題幹與標示正解是否扣緊課程內容、正解確實正確、無跑題' },
          kaodian: { type: 'string', description: '對應到的考點(一句話;若不對應填原因)' },
        },
        required: ['idx', 'belongs', 'match', 'kaodian'],
      },
    },
  },
  required: ['judgments'],
}

function blindPrompt(L) {
  return `你是國小四年級社會科專家。對「${L.title}」這一課的選擇題做盲測作答。

讀取題目檔(無標示答案)：${L.blind}
共 ${L.nq} 題,idx 從 0 到 ${L.nq - 1}。

對每一題：
1. 以四年級社會知識判斷最合理的正解選項(0-based index 對應 options 陣列)。
2. single_answer：判斷這題是否恰好只有一個明確正解。若選項有兩個都對、語意含糊、或正解不唯一,填 false。

把作答陣列另存到 jobs/_goal-work/${L.dir}/L${L.n}_blind_result.json(純JSON,格式 [{idx,answer_index,single_answer}]),然後回傳結構化結果。必須涵蓋全部 ${L.nq} 題,不可遺漏 idx。`
}

function judgePrompt(L) {
  return `你是國小四年級社會科命題審查官。審查「${L.title}」這一課既有題目是否扣緊課程、是否跑題。

讀取：
- 完整題目(含標示正解)：${L.shuffled}
- 本課考古題與考點：${L.kao}
- 本課單課研究紀錄(課程內容/考點地圖)：${L.rec}

共 ${L.nq} 題,idx 0 到 ${L.nq - 1}。對每一題判斷：
1. belongs：題目是否屬本課考點範疇(不是別課、不是超出四年級課綱)。
2. match：題幹與「標示正解(answer_index)」是否確實扣緊本課課程內容、標示正解正確無誤、無跑題、無事實錯誤。
3. kaodian：對應到的考點一句話;若 belongs 或 match 為 false,簡述原因。

把判斷陣列另存到 jobs/_goal-work/${L.dir}/L${L.n}_judge_result.json(純JSON,格式 [{idx,belongs,match,kaodian}]),然後回傳結構化結果。必須涵蓋全部 ${L.nq} 題。`
}

log(`啟動 ${lessons.length} 課 × (盲測+judge) = ${lessons.length * 2} 個 sonnet agent`)

const results = await parallel(lessons.map(L => () =>
  parallel([
    () => agent(blindPrompt(L), { label: `blind:${L.key}`, phase: '雙盲驗證', model: 'sonnet', schema: BLIND_SCHEMA }),
    () => agent(judgePrompt(L), { label: `judge:${L.key}`, phase: '雙盲驗證', model: 'sonnet', schema: JUDGE_SCHEMA }),
  ]).then(([blind, judge]) => ({
    key: L.key,
    nq: L.nq,
    blind: blind?.answers || null,
    judge: judge?.judgments || null,
  }))
))

return results
